/* 01. Paleta e medidas compartilhadas, equivalentes ao tema do Tailwind original. */
:root {
    --brand: #3b82f6;
    --brand-dark: #172554;
    --brand-deep: #050d29;
    --brand-muted: #2563eb;
    --brand-light: #dbeafe;
    --accent: #38bdf8;
    --ink: #111827;
    --muted: #55627a;
    --surface: #ffffff;
    --soft: #f3f7fc;
    --border: #dbe3ef;
    --radius: 16px;
    --header-height: 82px;
    --shadow: 0 12px 32px rgb(23 37 84 / 9%);
}

/* 02. Reset: inclui padding e bordas nas dimensões declaradas. */
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: calc(var(--header-height) + 24px);
}

body {
    margin: 0;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 16px;
    line-height: 1.6;
    color: var(--ink);
    background: var(--surface);
}

h1,
h2,
h3,
p {
    margin: 0;
}

h1,
h2,
h3 {
    line-height: 1.2;
}

h2 {
    font-size: clamp(1.8rem, 3vw, 2.6rem);
    letter-spacing: -0.04em;
}

a {
    color: inherit;
    text-decoration: none;
}

button,
input,
select {
    font: inherit;
}

button,
summary {
    cursor: pointer;
}

button {
    color: inherit;
}

[hidden] {
    display: none !important;
}

:focus-visible {
    outline: 3px solid var(--accent);
    outline-offset: 5px;
}

/* 03. Box model B01: contêiner com largura, padding, border e margin explícitos. */
.container {
    width: min(1240px, 100%);
    padding: 0 32px;
    border: 0 solid transparent;
    margin: 0 auto;
}

.narrow-container {
    max-width: 1000px;
}

/* B02: espaçamento das seções; height:auto permite acomodar seu conteúdo. */
.section {
    width: 100%;
    height: auto;
    padding: 76px 0;
    border: 0 solid transparent;
    margin: 0;
}

/* B03: link de teclado visível somente quando recebe foco. */
.skip-link {
    width: auto;
    padding: 12px 20px;
    border: 2px solid var(--accent);
    margin: 8px;
    position: fixed;
    top: -100px;
    left: 0;
    z-index: 100;
    background: var(--brand-dark);
    color: white;
}

.skip-link:focus {
    top: 0;
}

/* B04: cabeçalho fixo; borda delimita a área de navegação. */
.site-header {
    width: 100%;
    height: var(--header-height);
    padding: 0;
    border: 0 solid transparent;
    border-bottom: 1px solid var(--border);
    margin: 0;
    position: fixed;
    top: 0;
    z-index: 30;
    background: rgb(255 255 255 / 97%);
}

/* F01–F04: organiza marca, links e ações na mesma linha. */
.header-inner {
    height: 100%;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

/* B05: logotipo textual mantém a tipografia serifada original. */
.brand {
    width: auto;
    padding: 0;
    border: 0 solid transparent;
    margin: 0;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 32px;
    letter-spacing: -1.5px;
    white-space: nowrap;
}

.brand-accent {
    color: var(--brand-muted);
}

/* F05–F07: links alinhados e com quebra permitida em espaços estreitos. */
.desktop-nav {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 22px;
    color: var(--muted);
    font-size: 13px;
    font-weight: 700;
}

.desktop-nav a:hover,
.text-link:hover,
.drawer-links a:hover {
    color: var(--brand-muted);
}

/* B06 e F08–F10: botões centralizam texto e seta e têm área de toque ampla. */
.button {
    width: auto;
    min-height: 48px;
    padding: 12px 22px;
    border: 1px solid transparent;
    margin: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    border-radius: 999px;
    font-size: 14px;
    font-weight: 700;
    text-align: center;
    transition: background 180ms, transform 180ms;
}

.button:hover {
    transform: translateY(-2px);
}

.button-primary {
    background: var(--brand-muted);
    color: white;
}

.button-primary:hover {
    background: #1d4ed8;
}

.button-glass {
    background: rgb(255 255 255 / 10%);
    border-color: rgb(255 255 255 / 30%);
    color: white;
}

.button-glass:hover {
    background: rgb(255 255 255 / 20%);
}

.button-outline {
    border-color: var(--brand-dark);
    color: var(--brand-dark);
    background: transparent;
}

.button-light {
    color: var(--brand-dark);
    background: white;
}

/* B07 e F11–F14: as três barras são empilhadas e centralizadas. */
.menu-toggle {
    width: 44px;
    height: 44px;
    padding: 10px;
    border: 1px solid var(--border);
    margin: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 5px;
    flex-shrink: 0;
    background: transparent;
    border-radius: 10px;
}

.menu-toggle span {
    width: 20px;
    height: 2px;
    background: var(--brand-dark);
}

/* B08: diálogo usa a altura da tela e largura limitada. */
.menu-dialog {
    width: min(360px, 92vw);
    height: 100dvh;
    max-height: 100dvh;
    padding: 32px;
    border: 0 solid transparent;
    margin: 0 0 0 auto;
    color: var(--brand-dark);
}

body:has(dialog[open]) {
    overflow: hidden;
}

dialog::backdrop {
    background: rgb(5 13 41 / 65%);
}

.menu-heading,
.photo-dialog-heading {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
}

/* F15–F16: links do menu crescem verticalmente. */
.drawer-links {
    display: flex;
    flex-direction: column;
    gap: 22px;
    margin-top: 40px;
    font-weight: 700;
}

main {
    padding-top: var(--header-height);
}

/* B09: imagem original é incorporada ao final deste CSS como data URI. */
.hero {
    width: 100%;
    min-height: min(850px, calc(100svh - var(--header-height)));
    padding: 90px 0;
    border: 0 solid transparent;
    margin: 0;
    display: flex;
    align-items: center;
    color: white;
    background-image: linear-gradient(90deg, #050d29 0%, rgb(5 13 41 / 74%) 55%, rgb(5 13 41 / 28%)), var(--image-hero);
    background-size: cover;
    background-position: center;
}

.hero-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.eyebrow {
    color: var(--brand-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 14px;
}

.hero .eyebrow {
    color: var(--brand-light);
}

.hero h1 {
    font-size: clamp(3.4rem, 8vw, 6.5rem);
    letter-spacing: -0.065em;
    font-weight: 500;
}

.hero h1 span {
    color: #60a5fa;
}

/* B10: parágrafo tem largura limitada para facilitar a leitura. */
.hero-description {
    width: min(610px, 100%);
    padding: 0;
    border: 0 solid transparent;
    margin: 28px 0 0;
    color: #dce5f5;
    font-size: 18px;
    line-height: 1.8;
}

/* F17–F18: ações quebram a linha conforme o espaço disponível. */
.hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin-top: 36px;
}

.hero-note {
    font-size: 12px;
    color: #b4c5df;
    margin-top: 46px;
}

.highlights,
.contact-section {
    background: linear-gradient(100deg, #eff6ff, white);
}

/* B11 e F19–F22: título e controles ficam nas extremidades, com quebra responsiva. */
.section-heading {
    width: 100%;
    padding: 0;
    border: 0 solid transparent;
    margin: 0 0 32px;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 24px;
}

.section-heading p:not(.eyebrow) {
    color: var(--muted);
    margin-top: 12px;
}

.carousel-controls {
    display: flex;
    gap: 10px;
}

/* B12: botão de seta tem dimensões fixas e conteúdo centralizado. */
.icon-button {
    width: 44px;
    height: 44px;
    padding: 0;
    border: 1px solid var(--border);
    margin: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: white;
    font-size: 22px;
}

.icon-button:hover {
    border-color: var(--brand-muted);
    color: var(--brand-muted);
}

/* F23–F24: carrossel em linha; cards não encolhem. */
.featured-track {
    display: flex;
    flex-direction: row;
    gap: 24px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: thin;
    padding: 4px 4px 24px;
}

/* B13 e F25–F27: cada card possui foto e corpo em coluna. */
.featured-card {
    width: 300px;
    padding: 0;
    border: 1px solid var(--border);
    margin: 0;
    display: flex;
    flex-direction: column;
    flex: 0 0 300px;
    scroll-snap-align: start;
    overflow: hidden;
    background: white;
    border-radius: 12px 46px 12px 12px;
    box-shadow: var(--shadow);
}

.property-photo {
    height: 230px;
    background-size: cover;
    background-position: center;
    position: relative;
}

.photo-building {
    background-image: var(--image-building);
}

.photo-house {
    background-image: var(--image-house);
}

.photo-families {
    background-image: var(--image-families);
}

.photo-agency {
    background-image: var(--image-agency);
}

.photo-agent {
    background-image: var(--image-agent);
}

.photo-tag {
    position: absolute;
    top: 16px;
    left: 16px;
    padding: 4px 12px;
    background: white;
    color: var(--brand-dark);
    font-size: 11px;
    font-weight: 700;
    border-radius: 999px;
}

/* B14: padding do corpo separa o texto das bordas do card. */
.featured-body {
    width: 100%;
    padding: 22px;
    border: 0 solid transparent;
    margin: 0;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.card-location {
    color: var(--muted);
    font-size: 12px;
    margin-bottom: 8px;
}

.featured-body h3 {
    font-size: 20px;
    margin-bottom: 16px;
}

.property-facts {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 0;
    margin: 0 0 22px;
    list-style: none;
    font-size: 13px;
    color: var(--muted);
}

.property-facts li {
    display: flex;
    align-items: center;
    gap: 10px;
}

.property-facts li > span:first-child {
    color: var(--brand-muted);
}

.card-link {
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: var(--brand-muted);
    margin-top: auto;
    font-size: 13px;
    font-weight: 700;
}

.section-actions {
    display: flex;
    justify-content: center;
    margin-top: 32px;
}

.stats-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
}

/* B15: quatro indicadores se reorganizam em duas ou uma coluna. */
.stat-card {
    width: 250px;
    min-height: 210px;
    padding: 24px;
    border: 1px solid var(--border);
    margin: 0;
    flex: 1 1 230px;
    display: flex;
    align-items: flex-end;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    border-radius: var(--radius);
    background-size: cover;
    background-position: center;
    color: white;
}

.stat-card::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background: linear-gradient(20deg, #172554, rgb(23 37 84 / 75%), transparent);
}

.stat-content h3 {
    color: var(--brand-light);
    font-size: 14px;
}

.stat-content p {
    font-size: 32px;
    font-weight: 700;
    margin-top: 8px;
}

.demo-note {
    font-size: 12px;
    color: var(--muted);
    margin-top: 16px;
}

.catalog-section {
    min-height: 65vh;
    background: var(--soft);
}

/* B16: formulário usa box model completo e Flexbox para os campos. */
.filter-bar {
    width: 100%;
    padding: 24px;
    border: 1px solid #1e40af;
    margin: 0 0 36px;
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 16px;
    background: var(--brand-dark);
    color: white;
    border-radius: var(--radius);
}

.field {
    display: flex;
    flex-direction: column;
    flex: 1 1 160px;
    gap: 8px;
    min-width: 0;
}

.search-field {
    flex: 2 1 240px;
}

.field label {
    font-size: 12px;
    font-weight: 700;
}

/* B17: largura dos inputs respeita a largura disponível no formulário. */
.field input,
.field select {
    width: 100%;
    min-height: 48px;
    padding: 10px 12px;
    border: 1px solid var(--border);
    margin: 0;
    background: white;
    color: var(--ink);
    border-radius: 8px;
    font-size: 13px;
}

.results-heading {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 24px;
}

.results-heading h2 {
    font-size: 22px;
}

.results-heading p {
    color: var(--muted);
    font-size: 13px;
}

.catalog-grid {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    gap: 24px;
}

.catalog-grid .featured-card {
    width: calc((100% - 48px) / 3);
    flex: 0 1 calc((100% - 48px) / 3);
}

.card-price {
    font-weight: 700;
    color: var(--brand-dark);
    font-size: 20px;
    margin: 0 0 20px;
}

/* B18: resultado vazio tem área própria e espaçamento legível. */
.empty-state {
    width: 100%;
    padding: 64px 24px;
    border: 1px dashed var(--border);
    margin: 0;
    background: white;
    border-radius: var(--radius);
    text-align: center;
}

.empty-state p {
    margin: 12px 0 24px;
    color: var(--muted);
}

.text-link {
    color: var(--brand-muted);
    font-weight: 700;
    font-size: 14px;
}

.back-link {
    display: inline-block;
    margin-bottom: 32px;
}

.detail-heading {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 28px;
}

.detail-heading h1 {
    font-size: clamp(2rem, 4vw, 3rem);
    margin-bottom: 12px;
}

.detail-price {
    font-size: 28px;
    font-weight: 700;
    color: var(--brand-dark);
}

.gallery {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.gallery button {
    min-height: 380px;
    flex: 1 1 300px;
    border: 0;
    border-radius: var(--radius);
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: flex-end;
    justify-content: flex-end;
    padding: 20px;
}

.gallery span {
    padding: 8px 16px;
    background: rgb(5 13 41 / 85%);
    border-radius: 999px;
    color: white;
    font-size: 13px;
}

.detail-layout {
    display: flex;
    flex-wrap: wrap;
    gap: 40px;
    margin-top: 40px;
}

.detail-description {
    flex: 2 1 420px;
}

.detail-description h2,
.detail-description h3 {
    margin-bottom: 16px;
}

.detail-description p {
    color: var(--muted);
    margin-bottom: 24px;
}

.detail-facts {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    padding: 0;
    margin: 0 0 32px;
    list-style: none;
}

.detail-facts li {
    padding: 12px 20px;
    background: var(--soft);
    border-radius: 10px;
}

/* B19: painel lateral de contato. */
.visit-card {
    width: 320px;
    padding: 28px;
    border: 1px solid var(--border);
    margin: 0;
    flex: 1 1 280px;
    align-self: flex-start;
    display: flex;
    flex-direction: column;
    gap: 20px;
    border-radius: var(--radius);
    box-shadow: var(--shadow);
}

.visit-card h2 {
    font-size: 26px;
}

.faq-section {
    background: var(--soft);
}

/* B20: pergunta e resposta nativas, com borda e espaçamento completos. */
.faq-item {
    width: 100%;
    padding: 22px;
    border: 1px solid var(--border);
    margin: 0 0 12px;
    background: white;
    border-radius: 12px;
}

.faq-item summary {
    font-weight: 700;
    color: var(--brand-dark);
}

.faq-item p {
    color: var(--muted);
    margin-top: 16px;
}

.careers-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 24px;
}

.careers-inner p:not(.eyebrow) {
    margin-top: 16px;
    color: var(--muted);
}

.contact-heading {
    text-align: center;
    margin-bottom: 36px;
}

.contact-heading p:not(.eyebrow) {
    margin-top: 16px;
    color: var(--muted);
}

.contact-grid {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    gap: 24px;
}

/* B21: cards de contato com a mesma altura, graças ao alinhamento stretch. */
.contact-card {
    width: 300px;
    padding: 32px;
    border: 1px solid var(--border);
    margin: 0;
    flex: 1 1 300px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    background: white;
    border-radius: var(--radius);
    text-align: center;
    box-shadow: var(--shadow);
    overflow-wrap: anywhere;
}

.contact-icon {
    color: var(--brand-muted);
    font-size: 30px;
}

.contact-card p,
.contact-card small {
    color: var(--muted);
}

.contact-card a {
    color: var(--brand-muted);
    text-decoration: underline;
}

/* B22: rodapé separa créditos e informações de direitos autorais. */
.site-footer {
    width: 100%;
    padding: 42px 0 24px;
    border: 0 solid transparent;
    margin: 0;
    background: var(--brand-dark);
    color: var(--brand-light);
}

.footer-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 32px;
    padding-bottom: 32px;
}

.footer-brand .brand {
    color: white;
}

.footer-brand .brand span {
    color: #60a5fa;
}

.footer-brand p {
    font-size: 12px;
    margin-top: 10px;
}

.footer-credits h2 {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    color: #93c5fd;
    margin-bottom: 12px;
}

.footer-credits ul {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 20px;
    width: 320px;
    padding: 0;
    margin: 0;
    list-style: none;
    font-size: 12px;
}

.footer-credits li {
    flex: 1 1 140px;
}

.footer-bottom {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 12px;
    padding-top: 22px;
    border-top: 1px solid #314b82;
    font-size: 11px;
    color: #93acd4;
}

/* B23: galeria ampliada ocupa a tela sem ultrapassá-la. */
.photo-dialog {
    width: min(1100px, 94vw);
    padding: 20px;
    border: 1px solid var(--border);
    margin: auto;
    border-radius: var(--radius);
}

.photo-dialog-heading {
    margin-bottom: 16px;
}

.lightbox-image {
    width: 100%;
    height: 70vh;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    background-color: var(--soft);
}

.noscript-message {
    padding: 24px;
    text-align: center;
    color: var(--brand-dark);
    background: var(--brand-light);
}

/* 04. Tablet: duas colunas no catálogo e navegação compacta. */
@media (max-width: 1050px) {
    .desktop-nav {
        display: none;
    }

    .header-cta {
        margin-left: auto;
    }

    .catalog-grid .featured-card {
        flex-basis: calc((100% - 24px) / 2);
        width: calc((100% - 24px) / 2);
    }
}

/* 05. Celular: fluxo vertical, ações legíveis e sem rolagem horizontal na página. */
@media (max-width: 640px) {
    :root {
        --header-height: 72px;
    }

    .container {
        padding: 0 20px;
    }

    .header-inner {
        gap: 12px;
    }

    .brand {
        font-size: 28px;
    }

    .header-cta {
        display: none;
    }

    .section {
        padding: 48px 0;
    }

    .hero {
        min-height: 650px;
        padding: 64px 0;
    }

    .hero-description {
        font-size: 16px;
    }

    .hero-actions {
        flex-direction: column;
        align-items: stretch;
        width: 100%;
    }

    .hero-note {
        margin-top: 32px;
    }

    .featured-card {
        flex-basis: 270px;
        width: 270px;
    }

    .stats-grid {
        gap: 16px;
    }

    .stat-card {
        flex-basis: 100%;
    }

    .filter-bar {
        padding: 20px;
    }

    .field {
        flex-basis: 100%;
    }

    .filter-bar .button {
        width: 100%;
    }

    .catalog-grid .featured-card {
        width: 100%;
        flex-basis: 100%;
    }

    .gallery button {
        min-height: 250px;
    }

    .detail-description {
        flex-basis: 100%;
        min-width: 0;
    }

    .visit-card {
        width: 100%;
        flex-basis: 100%;
    }

    .contact-card {
        padding: 24px;
        width: 100%;
        flex-basis: 100%;
    }

    .footer-credits ul {
        width: 100%;
    }
}

/* 06. Respeita a preferência de acessibilidade por movimento reduzido. */
@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
        transition: none !important;
        animation: none !important;
    }
}

/* 07. Impressão: remove controles e mantém conteúdo relevante em papel. */
@media print {
    .site-header,
    .menu-dialog,
    .carousel-controls,
    .filter-bar,
    .photo-dialog {
        display: none;
    }

    main {
        padding-top: 0;
    }

    .section {
        padding: 24px 0;
    }

    .featured-track {
        flex-wrap: wrap;
        overflow: visible;
    }

    .featured-card,
    .contact-card {
        break-inside: avoid;
    }
}

